def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_defects = sum(1 for x in opp if x == 'D')

    # Detect always-defect
    if n >= 3 and opp_defects >= n - 1:
        return 'D'
    if n >= 5 and opp_defects >= n * 0.8:
        return 'D'

    # Endgame exploitation
    if n >= 98:
        return 'D'

    # Early cooperation
    if n < 10:
        return 'C'

    # Probing phase
    if n == 10:
        return 'D'
    if n == 11:
        return 'D'

    # n >= 12
    # Check opponent's reaction to our first defection: their action at round 12
    r2 = history[11][1] if n > 11 else 'C'

    if r2 == 'D':
        # They punished our first defection. Switch to cooperate mode.
        return 'C'
    else:
        # They are forgiving. Use windowed defection.
        recent_my_defects = sum(1 for x in my[-10:] if x == 'D')
        if recent_my_defects < 2:
            return 'D'
        return 'C'
